package app.kinnect.live;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

public class StoreActivity extends Activity implements StoreBilling.Events {
 public void setContentView(View view){super.setContentView(CommerceChrome.wrap(this,view));}
 @Override protected void attachBaseContext(Context base){super.attachBaseContext(I18n.localized(base));}
 private JSONObject catalog;private final Map<String,String> prices=new HashMap<>();private StoreBilling billing;private LinearLayout body;private String selectedTab="style";private boolean busy;private final java.util.ArrayDeque<String[]> receiptQueue=new java.util.ArrayDeque<>();
 private void styleBars(){int v=WebTheme.isDark(this)?1:0;getWindow().setStatusBarColor(WebDesign.BG[v]);getWindow().setNavigationBarColor(WebDesign.BG[v]);getWindow().getDecorView().setSystemUiVisibility(v==0?View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR:0);}
 private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 private String tr(String s){return I18n.t(s);}
 private int variant(){return WebTheme.isDark(this)?1:0;}
 private GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private TextView label(String text,int size){TextView v=new KinnectText(this);v.setText(text);v.setTextSize(size);v.setTypeface(ApprovedTypography.font(this,Typeface.NORMAL));v.setTextColor(WebDesign.INK[variant()]);v.setPadding(0,dp(5),0,dp(5));return v;}
 private Button button(String title,Runnable action){Button b=new KinnectButton(this);b.setText(title);b.setAllCaps(false);b.setTextSize(14);b.setTypeface(ApprovedTypography.font(this,Typeface.BOLD));b.setMinHeight(dp(46));b.setTextColor(Color.WHITE);b.setBackground(gradient(0xff7c3aed,0xffc026d3,14));b.setPadding(dp(12),dp(9),dp(12),dp(9));b.setOnClickListener(v->action.run());return b;}
 private boolean owns(String id){JSONArray owned=catalog==null?null:catalog.optJSONArray("owned");if(owned!=null)for(int i=0;i<owned.length();i++)if(id.equals(owned.optString(i)))return true;return false;}
 public void onCreate(Bundle saved){super.onCreate(saved);styleBars();NativeApi.shared.initialize(this,ServerConfig.DEFAULT_ORIGIN);billing=StoreBilling.create(this);load(true);}
 private void load(boolean connect){NativeApi.shared.call("GET","/api/store",null,(data,error,status)->{if(isFinishing()||isDestroyed())return;if(error!=null){message(error);if(catalog==null){LinearLayout page=new LinearLayout(this);page.setBackgroundColor(WebDesign.BG[variant()]);page.setOrientation(1);page.setPadding(dp(20),dp(20),dp(20),dp(20));page.addView(label(tr("Chưa tải được cửa hàng."),18));page.addView(button(tr("Thử lại"),()->load(true)));page.addView(button(tr("Quay lại"),()->finish()));setContentView(page);}return;}catalog=data;draw();if(connect){List<String> ids=new ArrayList<>();JSONArray products=catalog.optJSONArray("products");for(int i=0;i<products.length();i++)ids.add(products.optJSONObject(i).optString("id"));billing.connect(ids,catalog.optString("accountId"),this);}});}
 private void draw(){
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(WebDesign.BG[variant()]);setContentView(root);
  LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setBaselineAligned(false);top.setPadding(dp(12),0,dp(12),0);FrameLayout back=new FrameLayout(this);ImageView arrow=new ImageView(this);android.graphics.drawable.Drawable backIcon=WebIcons.load(this,"arrow-left");backIcon.setTint(WebDesign.INK[variant()]);arrow.setImageDrawable(backIcon);back.addView(arrow,new FrameLayout.LayoutParams(dp(20),dp(20),Gravity.CENTER));back.setContentDescription(tr("Quay lại"));back.setOnClickListener(v->finish());top.addView(back,new LinearLayout.LayoutParams(dp(36),dp(40)));TextView title=label(tr("Cửa hàng Kinnect"),22);title.setTypeface(null,Typeface.BOLD);android.graphics.drawable.Drawable shop=WebIcons.load(this,"shopping-bag");shop.setTint(WebDesign.PURPLE[variant()]);shop.setBounds(0,0,dp(23),dp(23));title.setCompoundDrawablePadding(dp(9));title.setTextSize(17);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(top);
  ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(20),dp(8),dp(20),dp(28));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  LinearLayout hero=new LinearLayout(this);hero.setOrientation(1);hero.setPadding(dp(22),dp(22),dp(22),dp(22));hero.setBackground(gradient(0xff5b21b6,0xffe748ac,24));TextView eyebrow=label("KINNECT SHOP",11);eyebrow.setTextColor(0xfff3e8ff);android.graphics.drawable.Drawable bag=WebIcons.load(this,"shopping-bag");bag.setTint(Color.WHITE);bag.setBounds(0,0,dp(20),dp(20));eyebrow.setCompoundDrawables(bag,null,null,null);eyebrow.setCompoundDrawablePadding(dp(8));hero.addView(eyebrow);TextView headline=label(tr("Thêm sắc màu.\nThêm chất riêng."),28);headline.setTextColor(Color.WHITE);headline.setTypeface(ApprovedTypography.font(this,Typeface.BOLD));hero.addView(headline);TextView sub=label(tr("Khung hồ sơ nổi bật. Sáng tạo theo cách của bạn."),13);sub.setTextColor(0xfff3e8ff);TextView badge=label("✦ "+tr("Xem thử miễn phí"),11);badge.setTextColor(Color.WHITE);hero.addView(badge);LinearLayout.LayoutParams heroAt=new LinearLayout.LayoutParams(-1,-2);heroAt.bottomMargin=dp(20);body.addView(hero,heroAt);

  LinearLayout tabs=new LinearLayout(this);tabs.setBaselineAligned(false);tabs.setGravity(Gravity.TOP);for(String key:new String[]{"style","studio","owned"}){String text=key.equals("style")?tr("Phong cách"):key.equals("studio")?"Studio Pro":tr("Đã sở hữu");Button tab=button(text,()->{selectedTab=key;draw();});tab.setSelected(selectedTab.equals(key));android.graphics.drawable.Drawable glyph=WebIcons.load(this,key.equals("style")?"palette":key.equals("studio")?"clapperboard":"check");glyph.setTint(selectedTab.equals(key)?Color.WHITE:WebDesign.PURPLE[variant()]);glyph.setBounds(0,0,dp(18),dp(18));tab.setCompoundDrawables(null,glyph,null,null);tab.setTextSize(11);tab.setMinWidth(0);tab.setMinimumWidth(0);tab.setMaxLines(2);tab.setGravity(Gravity.CENTER);tab.setCompoundDrawablePadding(dp(4));if(!selectedTab.equals(key)){tab.setTextColor(WebDesign.PURPLE[variant()]);tab.setBackground(round(WebDesign.CARD[variant()],14));}LinearLayout.LayoutParams tabAt=new LinearLayout.LayoutParams(0,dp(78),1);tabAt.setMargins(dp(3),0,dp(3),dp(14));tabs.addView(tab,tabAt);}body.addView(tabs);
  if(!catalog.optBoolean("billingReady")||!Distribution.PLAY)body.addView(label(tr("Xem thử miễn phí · Chưa mở bán"),11));
  JSONArray products=catalog.optJSONArray("products");int shown=0;for(int i=0;i<products.length();i++){JSONObject p=products.optJSONObject(i);if(selectedTab.equals("owned")?!owns(p.optString("id")):!selectedTab.equals(p.optString("kind")))continue;shown++;product(p);}
  if(shown==0)body.addView(label(tr("Bạn chưa có sản phẩm nào trong mục này."),16));
  body.addView(button(tr("Khôi phục giao dịch"),()->{billing.restore();load(false);}));
  if(!catalog.optString("appearance").isEmpty())body.addView(button(tr("Dùng phong cách mặc định"),()->apply("")));
  
 }
 private void product(JSONObject p){
  String id=p.optString("id");LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(16),dp(16),dp(16),dp(16));card.setBackground(round(WebDesign.CARD[variant()],20));LinearLayout.LayoutParams space=new LinearLayout.LayoutParams(-1,-2);space.topMargin=dp(12);space.bottomMargin=dp(16);body.addView(card,space);
  StoreArt artwork=new StoreArt(p);card.addView(artwork,new LinearLayout.LayoutParams(-1,dp(178)));artwork.setOnClickListener(v->new Sheet(this).setTitle(p.optString("name")).setView(preview(p)).setPositiveButton(tr("Đóng"),null).show());
  TextView name=label(p.optString("name"),20);name.setTypeface(null,Typeface.BOLD);card.addView(name);
  card.addView(button(tr("Xem thử"),()->new Sheet(this).setTitle(p.optString("name")).setMessage(p.optString(I18n.current().equals("en")?"descriptionEn":"description")+"\n\n"+tr("Xem thử không thay đổi hồ sơ hoặc cấp quyền sử dụng.")).setView(preview(p)).setPositiveButton(tr("Đóng"),null).show()));
  if(owns(id))card.addView(button(p.optString("kind").equals("style")?(id.equals(catalog.optString("appearance"))?tr("Đang sử dụng"):tr("Áp dụng")):tr("Mở Studio Pro"),()->{if(p.optString("kind").equals("style"))apply(id);else chooseMedia();}));
  else {String price=prices.get(id);Button buy=button(price==null?tr("Chưa mở bán"):tr("Mua một lần")+" · "+price,()->{if(!busy)new Sheet(this).setTitle(p.optString("name")).setMessage(tr("Mua một lần")+" · "+prices.get(id)+"\n\n"+tr("Quyền lợi gắn với tài khoản Kinnect đang đăng nhập.")).setPositiveButton(tr("Tiếp tục với Google Play"),(d,w)->billing.buy(id)).setNegativeButton(tr("Hủy"),null).show();});buy.setEnabled(price!=null&&catalog.optBoolean("billingReady")&&!busy);LinearLayout.LayoutParams buyAt=new LinearLayout.LayoutParams(-1,-2);buyAt.topMargin=dp(10);card.addView(buy,buyAt);if(price==null)card.addView(label(tr("Giá dự kiến, chưa phải giá thanh toán")+": "+java.text.NumberFormat.getIntegerInstance(new java.util.Locale("vi","VN")).format(p.optInt("referenceVnd"))+"đ",12));}
 }
 private GradientDrawable gradient(int a,int b,int radius){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{a,b});g.setCornerRadius(dp(radius));return g;}
 private final class StoreArt extends View {
  private final JSONObject product;private final Paint paint=new Paint(3);
  StoreArt(JSONObject value){super(StoreActivity.this);product=value;setContentDescription(value.optString("name")+" · "+tr("Xem thử"));}
  private void box(Canvas c,float l,float t,float r,float b,float radius,int color){paint.setShader(null);paint.setColor(color);c.drawRoundRect(l,t,r,b,radius,radius,paint);}
  protected void onDraw(Canvas source){super.onDraw(source);Canvas c=source;int save=c.save();c.scale(getWidth()/300f,getHeight()/178f);JSONArray colors=product.optJSONArray("colors");int a=Color.parseColor(colors.optString(0)),b=Color.parseColor(colors.optString(1));paint.setShader(new LinearGradient(0,0,300,178,a,b,Shader.TileMode.CLAMP));c.drawRoundRect(0,0,300,178,18,18,paint);paint.setShader(null);paint.setColor(0x33ffffff);c.drawCircle(55,30,110,paint);paint.setColor(0x22ffffff);c.drawCircle(265,160,85,paint);
   if(product.optString("kind").equals("studio")){for(int i=0;i<3;i++){float x=55+i*65;box(c,x,30+(i==1?-8:4),x+55,132+(i==1?8:0),10,0x55ffffff);android.graphics.drawable.Drawable icon=WebIcons.load(StoreActivity.this,i==0?"sparkles":i==1?"play":"clapperboard");icon.setTint(Color.WHITE);icon.setBounds((int)x+15,65,(int)x+40,90);icon.draw(c);}}
   else{paint.setColor(0x66ffffff);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(1);c.drawCircle(139,78,70,paint);paint.setStrokeWidth(4);c.drawCircle(125,70,36,paint);paint.setStyle(Paint.Style.FILL);paint.setColor(0x44ffffff);c.drawCircle(125,70,32,paint);paint.setColor(Color.WHITE);paint.setTypeface(ApprovedTypography.font(StoreActivity.this,Typeface.BOLD));paint.setTextSize(32);paint.setTextAlign(Paint.Align.CENTER);c.drawText("K",125,81,paint);box(c,157,85,246,124,12,0xeeffffff);box(c,170,96,230,101,3,a);box(c,170,108,212,112,3,b);}
   paint.setShader(null);paint.setColor(Color.WHITE);paint.setTextAlign(Paint.Align.CENTER);paint.setTypeface(ApprovedTypography.font(StoreActivity.this,Typeface.BOLD));paint.setTextSize(9);c.drawText(product.optString("kind").equals("studio")?"AURORA · TRAVEL · CINEMA":product.optString("name").toUpperCase()+" COLLECTION",150,157,paint);c.restoreToCount(save);
  }
 }
 private View preview(JSONObject product){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(12),dp(12),dp(12),dp(12));JSONArray colors=product.optJSONArray("colors");int color=Color.parseColor(colors.optString(0));TextView demo=label(product.optString("kind").equals("studio")?"Aurora · Travel · Cinema":"Kinnect · "+tr("Hồ sơ minh họa"),22);demo.setTextColor(color);demo.setGravity(Gravity.CENTER);GradientDrawable frame=round(WebDesign.CARD[variant()],18);frame.setStroke(dp(3),color);demo.setPadding(dp(16),dp(18),dp(16),dp(18));demo.setBackground(frame);box.addView(demo);TextView chat=label(tr("Xin chào! Đây là bản xem thử."),16);chat.setTextColor(Color.WHITE);chat.setPadding(dp(16),dp(16),dp(16),dp(16));chat.setBackground(round(color,18));LinearLayout.LayoutParams at=new LinearLayout.LayoutParams(-1,-2);at.topMargin=dp(18);box.addView(chat,at);return box;}
 private void chooseMedia(){try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("video/*"),700);}catch(Exception e){message(tr("Không mở được trình chọn video."));}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==700&&result==RESULT_OK&&data!=null&&data.getData()!=null)startActivity(new Intent(this,MediaEditActivity.class).setData(data.getData()).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION).putExtra("store_pro",true));}
 private void apply(String id){try{NativeApi.shared.call("POST","/api/store/style",new JSONObject().put("productId",id),(data,error,status)->{if(error!=null)message(error);else{message(tr("Đã áp dụng phong cách."));load(false);}});}catch(Exception e){message(tr("Chưa áp dụng được phong cách."));}}
 public void prices(Map<String,String> value){runOnUiThread(()->{if(isDestroyed())return;prices.clear();prices.putAll(value);if(catalog!=null)draw();});}
 public void receipt(String product,String token){runOnUiThread(()->{if(isDestroyed())return;receiptQueue.add(new String[]{product,token});verifyNext();});}
 private void verifyNext(){if(busy||receiptQueue.isEmpty()||isDestroyed())return;busy=true;String[] receipt=receiptQueue.remove();try{NativeApi.shared.call("POST","/api/store/verify",new JSONObject().put("productId",receipt[0]).put("purchaseToken",receipt[1]),(data,error,status)->{busy=false;if(isDestroyed())return;message(error!=null?error:data.optString("state").equals("PURCHASED")?tr("Giao dịch đã xác minh. Quyền lợi đã được cập nhật."):tr("Giao dịch đang chờ xử lý; chưa cấp quyền lợi."));if(receiptQueue.isEmpty())load(false);else verifyNext();});}catch(Exception e){busy=false;message(tr("Chưa xác minh được giao dịch."));verifyNext();}}
 public void message(String text){runOnUiThread(()->{if(!isDestroyed())Toast.makeText(this,I18n.t(text),Toast.LENGTH_LONG).show();});}
 protected void onDestroy(){if(billing!=null)billing.close();super.onDestroy();}
}
